function deposit(address from, uint256 amount) external {
    // VULNERABILITY: from is arbitrary — can be any address that approved this contract
    token.transferFrom(from, address(this), amount);
    balances[msg.sender] += amount;
}

function swap(
    address tokenIn,
    address tokenOut,
    uint256 amountIn,
    address from  // VULNERABILITY: attacker-controlled source address
) external returns (uint256 amountOut) {
    IERC20(tokenIn).transferFrom(from, address(this), amountIn);
    amountOut = _getAmountOut(amountIn, tokenIn, tokenOut);
    IERC20(tokenOut).transfer(msg.sender, amountOut);
}

struct MetaTx {
    address from;
    address to;
    uint256 amount;
    uint256 nonce;
    // No signature fields
}

function executeRelay(MetaTx calldata tx_) external {
    // VULNERABILITY: no signature check — from can be any address
    token.transferFrom(tx_.from, tx_.to, tx_.amount);
    emit Relayed(tx_.from, tx_.to, tx_.amount);
}

function deposit(uint256 amount) external {
    // SAFE: from is always the caller
    token.transferFrom(msg.sender, address(this), amount);
    balances[msg.sender] += amount;
    emit Deposited(msg.sender, amount);
}

function depositFrom(address from, uint256 amount) external {
    require(from == msg.sender, "unauthorized: from must be caller");
    token.transferFrom(from, address(this), amount);
    balances[from] += amount;
}

function depositWithPermit(
    address from,
    uint256 amount,
    uint256 deadline,
    uint8 v, bytes32 r, bytes32 s
) external {
    // EIP-2612: verify signature before transferFrom
    IERC20Permit(address(token)).permit(from, address(this), amount, deadline, v, r, s);
    token.transferFrom(from, address(this), amount);
    balances[from] += amount;
}

// msg.sender approves `delegate` to deposit on their behalf
mapping(address => mapping(address => bool)) public approvedSenders;

function approveDelegate(address delegate) external {
    approvedSenders[msg.sender][delegate] = true;
}

function depositFor(address from, address beneficiary, uint256 amount) external {
    require(approvedSenders[beneficiary][msg.sender], "not approved delegate");
    token.transferFrom(from, address(this), amount);
    balances[beneficiary] += amount;
}

function withdrawFor(uint256 userId, uint256 amount) external onlyOperator {
    address from = _getUser(userId);  // implementation not shown
    require(from != address(0), "user not found");
    token.transferFrom(from, treasury, amount);
}

function executeMetaTx(
    bytes32 messageHash,
    bytes calldata signature,
    address to,
    uint256 amount
) external {
    address from = ECDSA.recover(messageHash, signature);
    // MISSING: nonce check not shown
    token.transferFrom(from, to, amount);
}

// Called via Gelato relay with ERC2771 context
function depositRelayed(address from, uint256 amount) external onlyGelatoRelay {
    // from comes from Gelato relay calldata
    token.transferFrom(from, address(this), amount);
    balances[from] += amount;
}

abstract contract BaseVault {
    IERC20 public immutable token;

    function _getFromAddress() internal view virtual returns (address);

    function _doDeposit(uint256 amount) internal {
        address from = _getFromAddress();  // abstract
        token.transferFrom(from, address(this), amount);
    }
}

function batchTransfer(
    address[] calldata from,   // VULNERABILITY: arbitrary victim list
    address[] calldata to,
    uint256[] calldata amounts
) external {
    require(from.length == to.length && to.length == amounts.length);
    for (uint i = 0; i < from.length; i++) {
        // No check: from[i] == msg.sender
        token.transferFrom(from[i], to[i], amounts[i]);
    }
}

