mapping(address => bool) public operators;

function registerOperator() external {
    operators[msg.sender] = true;  // Anyone can become operator
}

function operatorTransfer(address from, address to, uint256 amount) external {
    require(operators[msg.sender], "not operator");
    // VULNERABILITY: operator can drain any from
    token.transferFrom(from, to, amount);
}

// Standard ERC20 allowance pattern
function pullPayment(address from, uint256 amount) external {
    // This will REVERT if from hasn't approved msg.sender for `amount`
    // ERC20 transferFrom checks: allowance[from][msg.sender] >= amount
    token.transferFrom(from, msg.sender, amount);
}

interface IToken {
    // Custom token — may not follow ERC20 standard
    function transferFrom(address from, address to, uint256 amount) external;
}

function collect(address from, uint256 amount) external onlyVault {
    IToken(token).transferFrom(from, address(this), amount);
}

function onFlashLoan(
    address initiator,
    address token,
    uint256 amount,
    uint256 fee,
    bytes calldata data  // attacker-controlled
) external override onlyLender returns (bytes32) {
    // VULNERABILITY: from decoded from attacker-controlled data
    (address from, uint256 pullAmount) = abi.decode(data, (address, uint256));
    IERC20(token).transferFrom(from, address(this), pullAmount);
    return keccak256("ERC3156FlashBorrower.onFlashLoan");
}
